#include "sched/sched.h"
#include "group/group.h"
#include "pthread/pthread.h"
#include "task/task.h"

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: task_join
 *
 * Description:
 *    A task can await termination of another task and retrieve the
 *    return value of the task.
 *
 * Input Parameters:
 *   pid - The ID of the task to join
 *   status - Location to return the task exit status
 *
 * Returned Value:
 *   0 if successful.  Otherwise, one of the following error codes:
 *
 *   EINVAL  The value specified by pid does not refer to a joinable task.
 *   ESRCH   No task could be found corresponding to that specified by the
 *           given task ID.
 *   EDEADLK A deadlock was detected or the value of pid specifies the
 *           calling task.
 *
 ****************************************************************************/

int task_join(pid_t pid, FAR int *status)
{
  FAR struct tcb_s *rtcb = this_task();
  FAR struct task_group_s *group = rtcb->group;
  FAR struct join_s *pjoin;
  int ret;

  sinfo("pid=%d group=%p\n", pid, group);
  DEBUGASSERT(group);

  /* First make sure that this is not an attempt to join to
   * ourself.
   */

  if (pid == nxsched_gettid())
    {
      return EDEADLK;
    }

  /* Make sure no other task is mucking with the data structures
   * while we are performing the following operations.
   */

  nxmutex_lock(&group->tg_joinlock);

  /* Find the join information associated with this task.
   * This can fail for one of three reasons:  (1) There is no
   * task associated with 'pid,' (2) the task is a pthread
   * and does not have join information, or (3) the task
   * was detached and has exited.
   */

  ret = pthread_findjoininfo(group, pid, &pjoin);
  if (ret == OK)
    {
      if (pjoin->detached)
        {
          nxmutex_unlock(&group->tg_joinlock);
          return EINVAL;
        }

      /* NOTE: sched_lock() is not enough for SMP
       * because another CPU would continue the task and exit
       * sequences so need to protect it with a critical section
       */

#ifdef CONFIG_SMP
      irqstate_t flags = enter_critical_section();
#endif

      /* We found the join info structure.  Increment for the reference
       * to the join structure that we have.  This will keep things
       * stable for we have to do
       */

      sched_lock();
      pjoin->crefs++;

      /* Check if the task is still running.  If not, then things are
       * simpler.  There are still race conditions to be concerned with.
       * For example, there could be multiple tasks executing in the
       * 'else' block below when we enter!
       */

      if (pjoin->terminated)
        {
          sinfo("Task has terminated\n");

          /* Get the task exit value from the terminated task. */

          if (status)
            {
              sinfo("exit_value=%p\n", pjoin->exit_value);
              *status = (int)(intptr_t)pjoin->exit_value;
            }
        }
      else
        {
          sinfo("Task is still running\n");

          /* Relinquish the data set semaphore.  Since pre-emption is
           * disabled, we can be certain that no task has the
           * opportunity to run between the time we relinquish the
           * join semaphore and the time that we wait on the task exit
           * semaphore.
           */

          nxmutex_unlock(&group->tg_joinlock);

          /* Take the task's task exit semaphore.  We will sleep here
           * until the task exits.  We need to exercise caution because
           * there could be multiple tasks waiting here for the same
           * task to exit.
           */

          nxsem_wait_uninterruptible(&pjoin->exit_sem);

          /* The task has exited! Get the task exit value */

          if (status)
            {
              *status = (int)(intptr_t)pjoin->exit_value;
              sinfo("exit_value=%p\n", pjoin->exit_value);
            }

          /* Post the task's data semaphore so that the exiting task
           * will know that we have received the data.
           */

          nxsem_post(&pjoin->data_sem);

          /* Retake the join semaphore, we need to hold this when
           * pthread_destroyjoin is called.
           */

          nxmutex_lock(&group->tg_joinlock);
        }

      /* Pre-emption is okay now. The logic still cannot be re-entered
       * because we hold the join semaphore
       */

      sched_unlock();

#ifdef CONFIG_SMP
      leave_critical_section(flags);
#endif

      /* Release our reference to the join structure and, if the reference
       * count decrements to zero, deallocate the join structure.
       */

      if (--pjoin->crefs <= 0)
        {
          pthread_destroyjoin(group, pjoin);
        }

      ret = OK;
    }

  nxmutex_unlock(&group->tg_joinlock);
  sinfo("Returning %d\n", ret);
  return ret;
}
EOF"}

