      nxsem_destroy(&join->data_sem);
      nxsem_destroy(&join->exit_sem);

      /* And deallocate the join structure */

      kmm_free(join);
    }

  /* Destroy the join list mutex */

  nxmutex_destroy(&group->tg_joinlock);
