/****************************************************************************
 * Name: pthread_find_detached
 *
 * Description:
 *   Find a detached thread entry in the list.
 *
 * Input Parameters:
 *   group - The task group
 *   pid - The thread ID to find
 *
 * Returned Value:
 *   A pointer to the detached entry or NULL if not found
 *
 ****************************************************************************/

static FAR struct detached_s *pthread_find_detached(FAR struct task_group_s *group,
                                                    pid_t pid)
{
  FAR struct detached_s *detached;

  for (detached = group->tg_detached;
       detached && detached->pid != pid;
       detached = detached->next);

  return detached;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: pthread_add_detached
 *
 * Description:
 *   Add a thread ID to the detached list.
 *
 * Input Parameters:
 *   group - The task group
 *   pid - The thread ID to add
 *
 * Returned Value:
 *   0 if successful, otherwise an error code
 *
 ****************************************************************************/

int pthread_add_detached(FAR struct task_group_s *group, pid_t pid)
{
  FAR struct detached_s *detached;

  /* Check if the thread is already in the detached list */

  detached = pthread_find_detached(group, pid);
  if (detached)
    {
      return OK;
    }

  /* Allocate a new detached entry */

  detached = kmm_zalloc(sizeof(struct detached_s));
  if (detached == NULL)
    {
      return ENOMEM;
    }

  /* Initialize the entry */

  detached->pid = pid;

  /* Add it to the list */

  detached->next = group->tg_detached;
  group->tg_detached = detached;

  return OK;
}

/****************************************************************************
 * Name: pthread_remove_detached
 *
 * Description:
 *   Remove a thread ID from the detached list.
 *
 * Input Parameters:
 *   group - The task group
 *   pid - The thread ID to remove
 *
 * Returned Value:
 *   0 if successful, otherwise an error code
 *
 ****************************************************************************/

int pthread_remove_detached(FAR struct task_group_s *group, pid_t pid)
{
  FAR struct detached_s *prev;
  FAR struct detached_s *detached;

  /* Find the entry with the matching pid */

  for (prev = NULL, detached = group->tg_detached;
       detached && detached->pid != pid;
       prev = detached, detached = detached->next);

  /* If not found, return OK (not an error) */

  if (detached == NULL)
    {
      return OK;
    }

  /* Remove it from the list */

  if (prev == NULL)
    {
      group->tg_detached = detached->next;
    }
  else
    {
      prev->next = detached->next;
    }

  /* Free the entry */

  kmm_free(detached);
  return OK;
}

/****************************************************************************
 * Name: pthread_is_detached
 *
 * Description:
 *   Check if a thread ID is in the detached list.
 *
 * Input Parameters:
 *   group - The task group
 *   pid - The thread ID to check
 *
 * Returned Value:
 *   true if the thread is detached, false otherwise
 *
 ****************************************************************************/

bool pthread_is_detached(FAR struct task_group_s *group, pid_t pid)
{
  return pthread_find_detached(group, pid) != NULL;
}
